# report_entries_40.ps1 - "Method used" and closing entries for roadmap Step 40 (report standard 2026-10-10/11).
# Result numbers are NOT typed here: the builder fills $global:S40 from the result files before dot-sourcing. ASCII only.

$s = $global:S40
$global:Methods["40"] = @{
  Approach = @(
    "The Run Simulation button of the dashboard now runs the Simulink operating model (sim of Transformer_Operating_Model, through run_transformer_simulation) for a full simulated day of 24 hours. The model itself is not changed: its subsystem SS8 (Step 37) already counts the sampling times and logs record_index. After the run, the function get_sampling_events turns the logged index into a table of sampling events (time, index, record_id), outside the model.",
    "The dashboard then plays the events back in time order. For each event it finds the row of that record_id in the loaded DGA file, selects it, and diagnoses it with the same code as the Diagnose button: the three conventional diagnoses in MATLAB and the ML diagnosis from the service. The events are marked on the temperature plot and listed in a table with the simulated hot-spot temperature at that moment. That temperature is operating context shown next to the record; it is not used to diagnose it.",
    "The link carries a record identifier only. The model never holds or produces a gas value: the gases are read from the file row of the record, as in Step 39. If no file is loaded the app uses dga_master.csv and says so; a record that is not in the file is reported and skipped; if the service is not reachable the run still completes and each event shows NOT_CONNECTED (decision D38)."
    )
  Why = @(
    "The roadmap asks for a working test bench in which the simulated transformer decides when a sample is taken and the dashboard diagnoses the sample of that moment. Passing only the record identifier keeps the rule of decision D4 (no gas value is generated by the model) true by construction.",
    "A single diagnosis function for the button and for the events means that Step 39's comparison with the offline results also covers the events; it is repeated here for the event records.",
    "Playing the events back after the run (instead of during it) keeps the simulation itself unchanged and repeatable.")
  Settings = @(
    @("Run", "24 h, default load profile of params_transformer.m (rated load), solver RelTol 1e-4 (D33)"),
    @("Sampling events", ("at " + $s.times + " h (illustrative, D35); " + $s.n + " events")),
    @("Playback", "events in time order; pause 0.5 s between events (0 s in the tests)"),
    @("Records", "the first held-out records of dga_master.csv, looked up by record_id in the loaded file"),
    @("Service", "http://127.0.0.1:8000/diagnose, as in Step 39"),
    @("Software", ("MATLAB " + $s.matlab + ", Simulink, Simscape; service: FastAPI (Step 38)")))
  Eqs = @()
  Tools = @("10_Dashboard_Client/DGADashboard.mlapp (Run Simulation button, EventTable); find_dga_row.m",
            "05_Simulink_Model/run_transformer_simulation.m (returns res.events), get_sampling_events.m",
            "10_Dashboard_Client/verify_step40.m (13 checks)",
            "00_Project_Admin/report_builder/update_register_step40.ps1 (register, glossary)")
  Refs = @("ST6", "SW4", "DF2")
}

$global:Closings["40"] = @{
  Achieved = @(
    "The Run Simulation button now runs the model for a full simulated day, marks the sampling events on the temperature plot, and diagnoses the record of each event in time order (decision D38).",
    ("All " + $s.nChecks + " checks pass: the day runs without error (" + $s.tRun + " s), the " + $s.n + " events equal those of Step 37, and the diagnosis at each event equals the offline conventional and ML results."),
    "The model file is unchanged (checksum), the plotted temperatures equal those of run_transformer_simulation, and no gas value comes from the model.",
    "Without the service, without a loaded file, and with a file that lacks some of the records, the run completes with a clear message.",
    "The 19 checks of Step 39 still pass with the new app.")
  Record = @(
    @("Step", "40 - Link the Simulink model to the dashboard"), @("Environment", "Claude Code (this chat) through the MATLAB MCP connection (roadmap role: Simulink Agentic Toolkit; D30)"),
    @("Completed", $s.completed), @("Status", "Done"),
    @("Main inputs", "Transformer_Operating_Model.slx with SS8; DGADashboard.mlapp of Step 39; the service of Step 38"),
    @("Main outputs", "DGADashboard.mlapp (updated), run_transformer_simulation.m (events), find_dga_row.m, verify_step40.m, results/step40_checks.csv, step40_event_run.csv; Figure 4.22 regenerated"),
    @("Checks", $s.checks),
    @("Decisions", "D38 (the link, the playback, the event table, the checks)"))
  Helps = @(
    "Step 41 runs the integrated system over every held-out record and logs each diagnosis and its response time: it can use the same helper functions and the same service call; the events of this step show the path that a simulated sample takes.",
    "Step 42 compares that log with the offline predictions; this step already shows identity for the event records.")
  Open = @(
    "The model was not changed in this step. The sampling times (6, 12, 18 and 22 h) are illustrative (D35).",
    "The playback pause (0.5 s) and the content of the event table are choices of decision D38.",
    "The events are played back after the simulation has finished, not while it runs; the simulation takes about a second, so no difference is visible to the user.",
    "DGADashboard.mlapp is still a file written with an internal serializer and should be opened once in App Designer (Step 39).",
    "The service must be started before the run, otherwise the ML column shows NOT_CONNECTED for every event.",
    "The researcher's error text from the earlier Simulink rerun has still not been supplied.")
  Exclude = @()
}

$global:StepSources["40"] = @("ST6", "SW4", "DF2", "DF48", "DF52", "DF74", "DF75")
